('al-usr-antonio-2026-2026-07-17','usr-antonio-2026','2026-07-17T07:30:00-03:00','Taquicardia de repouso sustentada','1 dia(s) consecutivo(s) fora do padrão (2026-07-17 a 2026-07-17).','low','heart_rate','74 bpm','64 bpm','Padrão compatível com síndrome febril prolongada (taquicardia de repouso + HRV reduzida + sono fragmentado). Em área endêmica, considerar leishmaniose visceral; correlacionar com hemograma e ferritina.',true),
