('al-usr-antonio-2026-2026-07-24','usr-antonio-2026','2026-07-24T07:30:00-03:00','Taquicardia de repouso sustentada','42 dia(s) consecutivo(s) fora do padrão (2026-07-24 a 2026-09-03).','high','heart_rate','90 bpm','64 bpm','Padrão compatível com síndrome febril prolongada (taquicardia de repouso + HRV reduzida + sono fragmentado). Em área endêmica, considerar leishmaniose visceral; correlacionar com hemograma e ferritina.',true),
('al-usr-antonio-2026-2026-09-05','usr-antonio-2026','2026-09-05T07:30:00-03:00','Taquicardia de repouso sustentada','1 dia(s) consecutivo(s) fora do padrão (2026-09-05 a 2026-09-05).','low','heart_rate','74 bpm','64 bpm','Padrão compatível com síndrome febril prolongada (taquicardia de repouso + HRV reduzida + sono fragmentado). Em área endêmica, considerar leishmaniose visceral; correlacionar com hemograma e ferritina.',true),
('al-usr-antonio-2026-2026-09-10','usr-antonio-2026','2026-09-10T07:30:00-03:00','Taquicardia de repouso sustentada','2 dia(s) consecutivo(s) fora do padrão (2026-09-10 a 2026-09-11).','low','heart_rate','76 bpm','64 bpm','Padrão compatível com síndrome febril prolongada (taquicardia de repouso + HRV reduzida + sono fragmentado). Em área endêmica, considerar leishmaniose visceral; correlacionar com hemograma e ferritina.',true)
