insert into rivio_clinical_events (id,patient_id,date,type,title,description,source) values
('ev-usr-antonio-2026-1','usr-antonio-2026','2026-07-05','sintoma','Início de febre diária','Febre vespertina, sudorese noturna e astenia. Relógio mostra taquicardia de repouso e queda de HRV desde esta data.','wearable'),
('ev-usr-antonio-2026-2','usr-antonio-2026','2026-07-12','consulta','UPA — suspeita de dengue','NS1 negativo. Tratamento sintomático; sem melhora.','pronto atendimento'),
('ev-usr-antonio-2026-3','usr-antonio-2026','2026-07-28','exame','Hemograma: pancitopenia','Hb 9,1; leucócitos 2.100; plaquetas 88 mil. Encaminhado à infectologia.','laboratório'),
('ev-usr-antonio-2026-4','usr-antonio-2026','2026-08-04','exame_imagem','Ultrassom de abdome','Esplenomegalia (baço 18 cm) e hepatomegalia leve.','imagem'),
('ev-usr-antonio-2026-5','usr-antonio-2026','2026-08-10','diagnostico','Leishmaniose visceral confirmada','Teste rápido rK39 positivo e amastigotas no aspirado de medula óssea.','infectologia'),
('ev-usr-antonio-2026-6','usr-antonio-2026','2026-08-11','internacao','Internação e início de anfotericina B lipossomal','3 mg/kg/dia por 7 dias com monitorização de função renal.','hospital'),
('ev-usr-antonio-2026-7','usr-antonio-2026','2026-08-19','internacao','Alta hospitalar','Afebril há 6 dias; creatinina 1,3 (monitorar).','hospital'),
('ev-usr-antonio-2026-8','usr-antonio-2026','2026-09-30','consulta','Retorno ambulatorial','Hemograma quase normalizado; baço em regressão.','infectologia'),
('ev-usr-antonio-2026-9','usr-antonio-2026','2026-10-30','consulta','Cura clínica inicial','Seguimento programado aos 6 e 12 meses para detectar recidiva.','infectologia')
on conflict (id) do nothing;

